impl Solution{pub fn partition(s:String)->Vec<Vec<String>>{fn pal(b:&[u8],mut l:usize,mut r:usize)->bool{while l<r{if b[l]!=b[r]{return false}l+=1;r-=1;}true}fn f(s:&str,st:usize,v:&mut Vec<String>,o:&mut Vec<Vec<String>>){if st==s.len(){o.push(v.clone());return}for e in st..s.len(){if pal(s.as_bytes(),st,e){v.push(s[st..=e].to_string());f(s,e+1,v,o);v.pop();}}}let mut o=vec![];f(&s,0,&mut vec![],&mut o);o}}
